//! Independent Empirical Adversarial Verification and Stress Harness for flightreader-core crypto module.
//!
//! Evaluates:
//! 1. Parity between `derive_key` and C# decompiled reference across all 65,536 combinations (256 seeds x 256 record types).
//! 2. Degenerate seeds (multiples of 15) and intermediate product arithmetic collapse analysis.
//! 3. Zero keystream collisions across the entire operational keyspace (57 x 256 = 14,592 keys) and full 65,536 space.
//! 4. Involutive roundtrip de-scrambling on randomized payloads, boundary conditions, and memory isolation.
//! 5. Empirical performance benchmarking for `derive_key` and `descramble_in_place`.

use flightreader_core::crypto::{
    calc_crc64, descramble_in_place, descramble_record_in_place, descramble_record_to_vec,
    descramble_slice, descramble_to_vec, derive_key, CRC64_TABLE, MAGIC_KEY,
};
use flightreader_core::error::FlightReaderError;
use std::collections::{HashMap, HashSet};
use std::time::Instant;

/// Independent replica of C# FlightReader.Sharp.Crc64 decompilation logic.
fn csharp_decompiled_get_key(rec_id: u8, seed: u8) -> [u8; 8] {
    let magic: u64 = 1311768467463790320;
    let num = magic.wrapping_mul(seed as u64);

    // sbyte[] array = new sbyte[8];
    // array[num4] = (sbyte)((num >>> (7 - num4) * 8) & 0xFFL);
    let mut mem = [0u8; 8];
    for i in 0..8 {
        mem[i] = ((num >> ((7 - i) * 8)) & 0xFF) as u8;
    }

    // CalcCrc64(array, (recId + key) % 256, 8)
    let mut crc = ((rec_id as u64) + (seed as u64)) % 256;
    for i in (0..8).rev() {
        let idx = ((mem[i] as u64 ^ crc) & 0xFF) as usize;
        crc = (crc >> 8) ^ CRC64_TABLE[idx];
    }

    // GetKeyArray: array[num] = (byte)((key2 >>> num * 8) & 0xFFL)
    crc.to_le_bytes()
}

/// Simple deterministic pseudo-random generator (xorshift64) for reproducible stress testing.
struct SimpleRng {
    state: u64,
}

impl SimpleRng {
    fn new(seed: u64) -> Self {
        Self {
            state: if seed == 0 { 0xCAFE_BABE_DEAD_BEEF } else { seed },
        }
    }

    fn next_u64(&mut self) -> u64 {
        let mut x = self.state;
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        self.state = x;
        x
    }

    fn fill_bytes(&mut self, dest: &mut [u8]) {
        for chunk in dest.chunks_mut(8) {
            let val = self.next_u64().to_le_bytes();
            let len = chunk.len();
            chunk.copy_from_slice(&val[..len]);
        }
    }
}

#[test]
fn test_adversarial_full_65536_keyspace_parity_with_csharp() {
    println!("\n=== [EMPIRICAL CHALLENGE 1] Full 65,536 Keyspace Parity Check ===");
    let mut mismatch_count = 0;

    for rec_id in 0..=255u8 {
        for seed in 0..=255u8 {
            let core_key = derive_key(rec_id, seed);
            let csharp_key = csharp_decompiled_get_key(rec_id, seed);

            if core_key != csharp_key {
                mismatch_count += 1;
                if mismatch_count <= 5 {
                    eprintln!(
                        "MISMATCH at rec_id={}, seed={}: core={:?}, csharp={:?}",
                        rec_id, seed, core_key, csharp_key
                    );
                }
            }
        }
    }

    println!("Total checked: 65,536 combinations (256 seeds x 256 record types)");
    println!("Mismatches: {}", mismatch_count);
    assert_eq!(
        mismatch_count, 0,
        "Bit-exact parity failure with C# decompiled reference!"
    );
}

#[test]
fn test_adversarial_degenerate_seeds_intermediate_collapse_and_diffusion() {
    println!("\n=== [EMPIRICAL CHALLENGE 2] Degenerate Seeds & Diffusion Audit ===");
    let degenerate_multiples: [u8; 16] = [
        0, 15, 30, 45, 60, 75, 90, 105, 120, 135, 150, 165, 180, 195, 210, 225,
    ];

    for &seed in &degenerate_multiples {
        let product = MAGIC_KEY.wrapping_mul(seed as u64);
        let bytes = product.to_be_bytes();
        let unique_lanes: HashSet<u8> = bytes.iter().copied().collect();

        // Verify arithmetic collapse: intermediate product has <= 2 unique byte values
        assert!(
            unique_lanes.len() <= 2,
            "Seed {} did not collapse to <= 2 lanes: {:?}",
            seed,
            unique_lanes
        );

        // Verify that despite this intermediate collapse, the resulting key for any record type
        // has high Shannon entropy / byte diversity
        for rec_id in [1, 2, 3, 4, 7, 10, 13, 14, 15, 56] {
            let key = derive_key(rec_id, seed);
            let key_unique_bytes: HashSet<u8> = key.iter().copied().collect();
            // In an 8-byte key, we expect high entropy (at least 5 unique bytes)
            assert!(
                key_unique_bytes.len() >= 5,
                "Low key entropy for degenerate seed {} rec_id {}: key={:?}, unique={}",
                seed,
                rec_id,
                key,
                key_unique_bytes.len()
            );
        }
    }
    println!("Degenerate seed arithmetic collapse successfully verified across all 16 multiples of 15.");
}

#[test]
fn test_adversarial_zero_keystream_collisions() {
    println!("\n=== [EMPIRICAL CHALLENGE 3] Keystream Collision Analysis ===");

    // 1. Operational keyspace: 57 standard record types x 256 seeds = 14,592 keys
    let mut operational_keys: HashMap<[u8; 8], (u8, u8)> = HashMap::with_capacity(57 * 256);
    let mut collision_count = 0;

    for rec_id in 1..=57u8 {
        for seed in 0..=255u8 {
            let key = derive_key(rec_id, seed);
            if let Some((prev_rec, prev_seed)) = operational_keys.insert(key, (rec_id, seed)) {
                eprintln!(
                    "COLLISION in operational space: key={:?} between (type={}, seed={}) and (type={}, seed={})",
                    key, prev_rec, prev_seed, rec_id, seed
                );
                collision_count += 1;
            }
        }
    }

    println!(
        "Operational keyspace (57 x 256): {} keys inserted, {} collisions detected.",
        operational_keys.len(),
        collision_count
    );
    assert_eq!(collision_count, 0, "Keystream collision in operational keyspace!");
    assert_eq!(operational_keys.len(), 57 * 256);

    // 2. Full 256 x 256 keyspace = 65,536 keys
    let mut full_keys: HashMap<[u8; 8], (u8, u8)> = HashMap::with_capacity(65536);
    let mut full_collisions = 0;
    for rec_id in 0..=255u8 {
        for seed in 0..=255u8 {
            let key = derive_key(rec_id, seed);
            if let Some((prev_rec, prev_seed)) = full_keys.insert(key, (rec_id, seed)) {
                eprintln!(
                    "COLLISION in full space: key={:?} between (type={}, seed={}) and (type={}, seed={})",
                    key, prev_rec, prev_seed, rec_id, seed
                );
                full_collisions += 1;
            }
        }
    }
    println!(
        "Full 256 x 256 keyspace: {} keys inserted, {} collisions detected.",
        full_keys.len(),
        full_collisions
    );
    assert_eq!(full_collisions, 0, "Keystream collision in 256x256 keyspace!");
    assert_eq!(full_keys.len(), 65536);
}

#[test]
fn test_adversarial_involutive_roundtrip_fuzzing() {
    println!("\n=== [EMPIRICAL CHALLENGE 4] Involutive Roundtrip Fuzzing ===");
    let mut rng = SimpleRng::new(0x1337_BEEF_CAFE);

    // Test across various payload sizes from 0 to 65,536 bytes
    let payload_sizes = [0, 1, 2, 3, 7, 8, 9, 15, 16, 17, 31, 32, 100, 255, 1024, 4096, 65536];

    for &size in &payload_sizes {
        let mut original = vec![0u8; size];
        rng.fill_bytes(&mut original);

        for rec_id in [1, 2, 4, 7, 10, 13, 14, 56] {
            for seed in [0, 1, 15, 42, 100, 135, 225, 255] {
                let key = derive_key(rec_id, seed);

                // In-place double XOR
                let mut buffer = original.clone();
                descramble_in_place(&mut buffer, key);
                if size > 0 && key != [0; 8] {
                    // Check ciphertext is actually modified
                    assert_ne!(buffer, original, "Ciphertext equals plaintext for size {}", size);
                }
                descramble_in_place(&mut buffer, key);
                assert_eq!(buffer, original, "In-place involutive roundtrip failed for size {}", size);

                // Slice roundtrip
                let mut dst1 = vec![0u8; size];
                let mut dst2 = vec![0u8; size];
                descramble_slice(&original, &mut dst1, key).unwrap();
                descramble_slice(&dst1, &mut dst2, key).unwrap();
                assert_eq!(dst2, original, "Slice roundtrip failed for size {}", size);

                // Vec roundtrip
                let vec_scrambled = descramble_to_vec(&original, key);
                let vec_recovered = descramble_to_vec(&vec_scrambled, key);
                assert_eq!(vec_recovered, original, "Vec roundtrip failed for size {}", size);

                // Record envelope roundtrip (seed + payload)
                if size > 0 {
                    let mut record = vec![seed];
                    record.extend_from_slice(&original);

                    // Scramble record payload in-place
                    descramble_in_place(&mut record[1..], key);
                    assert_eq!(record[0], seed, "Seed byte corrupted during scrambling!");

                    // Recover record using descramble_record_in_place
                    let recovered_slice = descramble_record_in_place(&mut record, rec_id).unwrap();
                    assert_eq!(recovered_slice, original.as_slice(), "descramble_record_in_place failed for size {}", size);
                }
            }
        }
    }
    println!("Involutive roundtrip verified across all sizes and random payloads.");
}

#[test]
fn test_adversarial_error_boundaries_and_memory_safety() {
    println!("\n=== [EMPIRICAL CHALLENGE 5] Error Boundaries & Negative Testing ===");

    // 1. descramble_slice buffer overflow
    let key = [1, 2, 3, 4, 5, 6, 7, 8];
    let src = [0xAA; 16];
    let mut undersized_dst = [0u8; 15];
    let err = descramble_slice(&src, &mut undersized_dst, key);
    assert_eq!(
        err,
        Err(FlightReaderError::BufferOverflow {
            required: 16,
            capacity: 15,
        })
    );

    // 2. descramble_record_in_place on sub-minimal buffers
    let mut empty_buf: [u8; 0] = [];
    assert_eq!(
        descramble_record_in_place(&mut empty_buf, 1),
        Err(FlightReaderError::PayloadTooShort {
            minimum: 2,
            available: 0,
        })
    );

    let mut single_byte_buf = [42u8];
    assert_eq!(
        descramble_record_in_place(&mut single_byte_buf, 1),
        Err(FlightReaderError::PayloadTooShort {
            minimum: 2,
            available: 1,
        })
    );

    // 3. descramble_record_to_vec on sub-minimal buffers
    assert_eq!(
        descramble_record_to_vec(&empty_buf, 1),
        Err(FlightReaderError::PayloadTooShort {
            minimum: 2,
            available: 0,
        })
    );
    assert_eq!(
        descramble_record_to_vec(&single_byte_buf, 1),
        Err(FlightReaderError::PayloadTooShort {
            minimum: 2,
            available: 1,
        })
    );

    println!("All negative error conditions properly caught and typed.");
}

#[test]
fn test_adversarial_performance_benchmarks() {
    println!("\n=== [EMPIRICAL CHALLENGE 6] Performance Benchmarks ===");

    // Benchmark 1: derive_key throughput
    let derive_iterations = 2_000_000;
    let t0 = Instant::now();
    let mut checksum_sink: u64 = 0;
    for i in 0..derive_iterations {
        let rec_id = (i % 57 + 1) as u8;
        let seed = (i % 256) as u8;
        let key = derive_key(rec_id, seed);
        checksum_sink = checksum_sink.wrapping_add(u64::from_le_bytes(key));
    }
    let elapsed_derive = t0.elapsed();
    let keys_per_sec = (derive_iterations as f64) / elapsed_derive.as_secs_f64();

    println!("sink: {:x}", checksum_sink);
    println!(
        "[PERF BENCHMARK] derive_key: {} iterations in {:.4}s -> {:,.0} keys/second",
        derive_iterations,
        elapsed_derive.as_secs_f64(),
        keys_per_sec
    );

    // Benchmark 2: descramble_in_place throughput (100-byte packets, typical DJI telemetry)
    let packet_size = 100;
    let packet_iterations = 500_000;
    let key = [0x5D, 0x73, 0x0A, 0x59, 0x50, 0xF5, 0x13, 0x01];
    let mut packet = vec![0x55u8; packet_size];

    let t1 = Instant::now();
    for _ in 0..packet_iterations {
        descramble_in_place(&mut packet, key);
    }
    let elapsed_packets = t1.elapsed();
    let packets_per_sec = (packet_iterations as f64) / elapsed_packets.as_secs_f64();
    let mb_per_sec = (packets_per_sec * (packet_size as f64)) / (1024.0 * 1024.0);

    println!(
        "[PERF BENCHMARK] descramble_in_place (100B records): {} records in {:.4}s -> {:,.0} records/sec ({:.2} MB/s)",
        packet_iterations,
        elapsed_packets.as_secs_f64(),
        packets_per_sec,
        mb_per_sec
    );

    // Benchmark 3: descramble_in_place throughput (64KB blocks, bulk throughput)
    let block_size = 64 * 1024;
    let block_iterations = 10_000;
    let mut block = vec![0xAAu8; block_size];

    let t2 = Instant::now();
    for _ in 0..block_iterations {
        descramble_in_place(&mut block, key);
    }
    let elapsed_blocks = t2.elapsed();
    let blocks_per_sec = (block_iterations as f64) / elapsed_blocks.as_secs_f64();
    let bulk_mb_per_sec = (blocks_per_sec * (block_size as f64)) / (1024.0 * 1024.0);

    println!(
        "[PERF BENCHMARK] descramble_in_place (64KB bulk): {} blocks in {:.4}s -> {:.2} MB/s",
        block_iterations,
        elapsed_blocks.as_secs_f64(),
        bulk_mb_per_sec
    );

    // Assert minimum performance thresholds in release mode
    #[cfg(not(debug_assertions))]
    {
        assert!(
            keys_per_sec >= 1_000_000.0,
            "derive_key throughput below 1M keys/sec threshold in release mode: {:,.0}",
            keys_per_sec
        );
        assert!(
            mb_per_sec >= 200.0,
            "descramble_in_place throughput below 200 MB/s threshold in release mode: {:.2} MB/s",
            mb_per_sec
        );
    }
}

